contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: caller will be this contract (msg.sender to C). amount is Ether to send to Deposit.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // read before values
        uint beforeBalance = c.balances(address(this));
        uint beforeContractBal = address(c).balance;

        bool reverted;
        // call Deposit with value = amount
        try c.Deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = c.balances(address(this));
        uint afterContractBal = address(c).balance;

        // If Deposit did not revert, then it must have been called with amount > MinDeposit
        // and the stored balance increased by exactly amount and contract balance increased by amount.
        // If it reverted, then either nothing changed or change is allowed only if call did not execute (we expect no change).
        assert(
            (!reverted && amount > c.MinDeposit() && afterBalance == beforeBalance + amount && afterContractBal == beforeContractBal + amount)
            || (reverted && afterBalance == beforeBalance && afterContractBal == beforeContractBal)
        );
    }

    // allow receiving Ether so tests can fund this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test CashOut behavior for this contract acting as caller (this contract is msg.sender to c).
    // Parameter _am is the requested withdrawal amount. The function is payable so the test can be funded,
    // but CashOut does not require sending Ether with the call; depositing beforehand is done via Deposit if needed.
    function run(uint _am, uint depositAmount) public payable {
        // ensure this test contract has enough balance to make any Deposit we choose
        require(address(this).balance >= depositAmount);

        // Read before values
        uint beforeStored = c.balances(address(this));
        uint beforeContractBal = address(c).balance;

        // Optionally top-up stored balance by calling Deposit with depositAmount
        if (depositAmount > 0) {
            // Deposit only increases stored balance when msg.value > MinDeposit and does not revert on its own except require overflow which is benign here.
            // call Deposit with value depositAmount
            try c.Deposit{value: depositAmount}() {
                // ignored
            } catch {
                // ignore failures of Deposit; we still observe state afterwards
            }
        }

        // Re-read stored balance and contract balance after optional deposit
        uint midStored = c.balances(address(this));
        uint midContractBal = address(c).balance;

        // Call CashOut and capture whether it reverted
        bool reverted;
        try c.CashOut{value:0}(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after values
        uint afterStored = c.balances(address(this));
        uint afterContractBal = address(c).balance;

        // General rule:
        // 1) Stored balance never increases due to CashOut (afterStored <= midStored).
        // 2) Contract balance never increases due to CashOut (afterContractBal <= midContractBal).
        // 3) If CashOut succeeded (not reverted) then stored balance decreased by exactly _am and contract balance decreased by exactly _am.
        // (All comparisons are observable via public getters and address(c).balance.)
        assert(
            // stored and contract balance never grow because CashOut only sends Ether out if successful
            afterStored <= midStored && afterContractBal <= midContractBal
            && (
                // either it reverted and then nothing increased (but decreases could still have happened prior to revert; however CashOut reverts after failed external call, and state write to balances happens before external call, so if reverted then balances stayed as before the call)
                (reverted && afterStored == midStored && afterContractBal == midContractBal)
                // or it succeeded and both decreased by exactly _am
                || (!reverted && midStored >= _am && afterStored == midStored - _am && midContractBal >= _am && afterContractBal == midContractBal - _am)
            )
        );
    }

    // allow receiving Ether so this contract can be funded in tests and accept refunds
    receive() external payable {}
}

